assert("Layout");
assert("List");
assert("Mouse");
assert("Position");
assert("Scale");
assert("Text");
assert("WindowStyle");

assert(null, "default");
assert("", "default");
assert("other", "default");
System.Console.Write("RAN");

void assert(string input, string expected = null)
{
    if (C.M(input) != (expected ?? input))
    {
        throw new System.Exception($"{input} produced {C.M(input)}");
    }
}

public class C
{
    public static string M(string value)
    {
        return value switch
        {
            "Action" => "Action",
            "Appearance" => "Appearance",
            "Asynchronous" => "Asynchronous",
            "Behavior" => "Behavior",
            "Config" => "Config",
            "Data" => "Data",
            "DDE" => "DDE",
            "Default" => "Default",
            "Design" => "Design",
            "DragDrop" => "DragDrop",
            "Focus" => "Focus",
            "Font" => "Font",
            "Format" => "Format",
            "Key" => "Key",
            "Layout" => "Layout",
            "List" => "List",
            "Mouse" => "Mouse",
            "Position" => "Position",
            "Scale" => "Scale",
            "Text" => "Text",
            "WindowStyle" => "WindowStyle",
            _ => "default"
        };
    }
}
